content.content:
1	/* =========================================
2	   INCIDENT DASHBOARD — IncidentDashboard.css
3	   Extends Management.css + Users.css patterns.
4	   ========================================= */
5	
6	/* --- Summary Stat Cards --- */
7	.inc-stats-grid {
8	  display: grid;
9	  grid-template-columns: repeat(4, 1fr);
10	  gap: 20px;
11	  margin-bottom: 24px;
12	}
13	
14	.inc-stat-card {
15	  background: #1e2539;
16	  border: 1px solid #2d364f;
17	  border-radius: 12px;
18	  padding: 22px 24px;
19	  position: relative;
20	  overflow: hidden;
21	  transition: transform 0.2s, border-color 0.2s;
22	}
23	
24	.inc-stat-card::before {
25	  content: '';
26	  position: absolute;
27	  top: 0;
28	  left: 0;
29	  width: 4px;
30	  height: 100%;
31	}
32	
33	.inc-stat-card:hover {
34	  transform: translateY(-2px);
35	  border-color: #334155;
36	}
37	
38	.inc-stat-blue::before  { background: #3b82f6; }
39	.inc-stat-red::before   { background: #f87171; }
40	.inc-stat-orange::before { background: #f59e0b; }
41	.inc-stat-green::before  { background: #34d399; }
42	
43	.inc-stat-blue  { border-left: 4px solid #3b82f6; }
44	.inc-stat-red   { border-left: 4px solid #f87171; }
45	.inc-stat-orange { border-left: 4px solid #f59e0b; }
46	.inc-stat-green  { border-left: 4px solid #34d399; }
47	
48	/* Override the ::before left bar since we're using border-left */
49	.inc-stat-card::before { display: none; }
50	
51	.inc-stat-value {
52	  font-size: 2.2rem;
53	  font-weight: 800;
54	  color: #f8fafc;
55	  line-height: 1;
56	  margin-bottom: 6px;
57	}
58	
59	.inc-stat-blue  .inc-stat-value { color: #60a5fa; }
60	.inc-stat-red   .inc-stat-value { color: #f87171; }
61	.inc-stat-orange .inc-stat-value { color: #f59e0b; }
62	.inc-stat-green  .inc-stat-value { color: #34d399; }
63	
64	.inc-stat-label {
65	  font-size: 0.78rem;
66	  text-transform: uppercase;
67	  letter-spacing: 0.08em;
68	  font-weight: 700;
69	  color: #64748b;
70	}
71	
72	/* --- AI vs Manual source counter chips --- */
73	.inc-source-counter {
74	  display: flex;
75	  align-items: center;
76	  gap: 10px;
77	  margin-bottom: 16px;
78	}
79	
80	.inc-source-chip {
81	  display: inline-flex;
82	  align-items: center;
83	  padding: 4px 12px;
84	  border-radius: 999px;
85	  font-size: 0.75rem;
86	  font-weight: 700;
87	  letter-spacing: 0.04em;
88	  white-space: nowrap;
89	  border: 1px solid;
90	}
91	
92	.inc-source-chip-ai {
93	  background: rgba(192, 132, 252, 0.10);
94	  color: #c084fc;
95	  border-color: rgba(192, 132, 252, 0.25);
96	}
97	
98	.inc-source-chip-manual {
99	  background: rgba(148, 163, 184, 0.09);
100	  color: #94a3b8;
101	  border-color: rgba(148, 163, 184, 0.20);
102	}
103	
104	.inc-source-chip-divider {
105	  color: #334155;
106	  font-size: 0.85rem;
107	  user-select: none;
108	}
109	
110	/* --- Filter Bar --- */
111	.inc-filter-bar {
112	  display: flex;
113	  gap: 12px;
114	  align-items: center;
115	  margin-bottom: 16px;
116	  flex-wrap: wrap;
117	}
118	
119	.inc-search-input {
120	  flex: 1;
121	  min-width: 200px;
122	  padding: 9px 14px;
123	  background: #1e293b;
124	  border: 1px solid #334155;
125	  border-radius: 8px;
126	  color: #e2e8f0;
127	  font-size: 0.9rem;
128	  outline: none;
129	  transition: border-color 0.2s;
130	}
131	
132	.inc-search-input::placeholder {
133	  color: #475569;
134	}
135	
136	.inc-search-input:focus {
137	  border-color: #3b82f6;
138	}
139	
140	.inc-select {
141	  padding: 9px 12px;
142	  background: #1e293b;
143	  border: 1px solid #334155;
144	  border-radius: 8px;
145	  color: #e2e8f0;
146	  font-size: 0.85rem;
147	  outline: none;
148	  cursor: pointer;
149	  transition: border-color 0.2s;
150	}
151	
152	.inc-select:focus {
153	  border-color: #3b82f6;
154	}
155	
156	/* --- Incident Badges --- */
157	.inc-badge {
158	  display: inline-block;
159	  padding: 4px 10px;
160	  border-radius: 6px;
161	  font-size: 0.72rem;
162	  font-weight: 700;
163	  text-transform: uppercase;
164	  letter-spacing: 0.04em;
165	  white-space: nowrap;
166	}
167	
168	/* Severity */
169	.inc-severity-critical {
170	  background: rgba(248, 113, 113, 0.12);
171	  color: #f87171;
172	  border: 1px solid rgba(248, 113, 113, 0.25);
173	}
174	
175	.inc-severity-high {
176	  background: rgba(245, 158, 11, 0.12);
177	  color: #f59e0b;
178	  border: 1px solid rgba(245, 158, 11, 0.25);
179	}
180	
181	.inc-severity-medium {
182	  background: rgba(251, 191, 36, 0.12);
183	  color: #fbbf24;
184	  border: 1px solid rgba(251, 191, 36, 0.25);
185	}
186	
187	.inc-severity-low {
188	  background: rgba(59, 130, 246, 0.12);
189	  color: #60a5fa;
190	  border: 1px solid rgba(59, 130, 246, 0.25);
191	}
192	
193	/* AI Source */
194	.inc-source-fr {
195	  background: rgba(56, 189, 248, 0.12);
196	  color: #38bdf8;
197	  border: 1px solid rgba(56, 189, 248, 0.25);
198	}
199	
200	.inc-source-od {
201	  background: rgba(192, 132, 252, 0.12);
202	  color: #c084fc;
203	  border: 1px solid rgba(192, 132, 252, 0.25);
204	}
205	
206	/* Resolution Status */
207	.inc-status-active {
208	  background: rgba(248, 113, 113, 0.12);
209	  color: #f87171;
210	  border: 1px solid rgba(248, 113, 113, 0.25);
211	}
212	
213	.inc-status-investigating {
214	  background: rgba(245, 158, 11, 0.12);
215	  color: #f59e0b;
216	  border: 1px solid rgba(245, 158, 11, 0.25);
217	}
218	
219	.inc-status-escalated {
220	  background: rgba(251, 191, 36, 0.12);
221	  color: #fbbf24;
222	  border: 1px solid rgba(251, 191, 36, 0.25);
223	}
224	
225	.inc-status-cleared {
226	  background: rgba(52, 211, 153, 0.12);
227	  color: #34d399;
228	  border: 1px solid rgba(52, 211, 153, 0.25);
229	}
230	
231	/* --- Detail Modal (wider than default modal-content) --- */
232	.inc-detail-modal {
233	  background: #1e293b;
234	  border: 1px solid #334155;
235	  border-radius: 16px;
236	  padding: 30px;
237	  width: 90%;
238	  max-width: 620px;
239	  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6);
240	  animation: scaleUp 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
241	}
242	
243	.inc-modal-header {
244	  display: flex;
245	  justify-content: space-between;
246	  align-items: flex-start;
247	  margin-bottom: 24px;
248	  padding-bottom: 16px;
249	  border-bottom: 1px solid #334155;
250	}
251	
252	.inc-modal-header h2 {
253	  font-size: 1.25rem;
254	  font-weight: 700;
255	  color: #f8fafc;
256	  margin: 0 0 4px 0;
257	}
258	
259	/* --- Two-column detail grid --- */
260	.inc-detail-grid {
261	  display: grid;
262	  grid-template-columns: 1fr 1fr;
263	  gap: 16px 24px;
264	  margin-bottom: 20px;
265	}
266	
267	.inc-detail-item {
268	  display: flex;
269	  flex-direction: column;
270	  gap: 4px;
271	  min-width: 0;
272	}
273	
274	.inc-detail-label {
275	  font-size: 0.7rem;
276	  text-transform: uppercase;
277	  letter-spacing: 0.08em;
278	  font-weight: 700;
279	  color: #64748b;
280	}
281	
282	.inc-detail-value {
283	  font-size: 0.92rem;
284	  color: #e2e8f0;
285	  font-weight: 500;
286	  overflow-wrap: break-word;
287	  word-break: break-word;
288	  min-width: 0;
289	}
290	
291	/* --- Notes section --- */
292	.inc-notes-section {
293	  display: flex;
294	  flex-direction: column;
295	  gap: 8px;
296	  padding-top: 16px;
297	  border-top: 1px solid #1e293b;
298	}
299	
300	.inc-notes-box {
301	  background: #0f172a;
302	  border: 1px solid #334155;
303	  border-radius: 8px;
304	  padding: 12px 16px;
305	  color: #94a3b8;
306	  font-size: 0.88rem;
307	  line-height: 1.6;
308	  min-height: 56px;
309	}
310	
311	/* --- Person cell — reuse user-info pattern inline --- */
312	.inc-person-cell {
313	  display: flex;
314	  align-items: center;
315	  gap: 10px;
316	}
317	
318	.inc-person-initial {
319	  width: 28px;
320	  height: 28px;
321	  background: linear-gradient(135deg, #3b82f6, #0891b2);
322	  color: white;
323	  border-radius: 50%;
324	  display: flex;
325	  justify-content: center;
326	  align-items: center;
327	  font-weight: 700;
328	  font-size: 0.78rem;
329	  flex-shrink: 0;
330	}
331	
332	/* =========================================
333	   RESPONSIVE
334	   ========================================= */
335	@media (max-width: 1024px) {
336	  .inc-stats-grid {
337	    grid-template-columns: repeat(2, 1fr);
338	  }
339	}
340	
341	@media (max-width: 768px) {
342	  .inc-stats-grid {
343	    grid-template-columns: 1fr 1fr;
344	    gap: 12px;
345	  }
346	
347	  .inc-filter-bar {
348	    flex-direction: column;
349	    align-items: stretch;
350	  }
351	
352	  .inc-search-input,
353	  .inc-select {
354	    width: 100%;
355	  }
356	
357	  .inc-detail-grid {
358	    grid-template-columns: 1fr;
359	  }
360	
361	  .inc-detail-modal {
362	    padding: 20px;
363	    width: 95%;
364	  }
365	}
366	
367	@media (max-width: 480px) {
368	  .inc-stats-grid {
369	    grid-template-columns: 1fr;
370	  }
371	}
372	
373	/* =========================================
374	   CRUD ADDITIONS
375	   ========================================= */
376	
377	/* --- "+ Log Incident" header button --- */
378	.inc-create-btn {
379	  background: linear-gradient(135deg, #2563eb, #0891b2);
380	  color: white;
381	  border: 1px solid rgba(147, 197, 253, 0.35);
382	  padding: 10px 18px;
383	  border-radius: 8px;
384	  font-weight: 700;
385	  font-size: 0.88rem;
386	  cursor: pointer;
387	  white-space: nowrap;
388	  transition: transform 0.15s, box-shadow 0.15s;
389	  box-shadow: 0 6px 18px rgba(37, 99, 235, 0.2);
390	  align-self: center;
391	}
392	
393	.inc-create-btn:hover {
394	  transform: translateY(-1px);
395	  box-shadow: 0 10px 24px rgba(37, 99, 235, 0.35);
396	}
397	
398	/* --- Create modal (wider than detail modal) --- */
399	.inc-create-modal {
400	  background: #1e293b;
401	  border: 1px solid #334155;
402	  border-radius: 16px;
403	  padding: 30px;
404	  width: 90%;
405	  max-width: 660px;
406	  max-height: 90vh;
407	  overflow-y: auto;
408	  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6);
409	  animation: scaleUp 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
410	}
411	
412	/* --- Form grid inside create modal --- */
413	.inc-form {
414	  margin-top: 20px;
415	}
416	
417	.inc-form-grid {
418	  display: grid;
419	  grid-template-columns: 1fr 1fr;
420	  gap: 16px 20px;
421	}
422	
423	.inc-form-group {
424	  display: flex;
425	  flex-direction: column;
426	  gap: 6px;
427	}
428	
429	.inc-form-full {
430	  grid-column: 1 / -1;
431	}
432	
433	/* --- Textarea (create form + edit mode) --- */
434	.inc-notes-textarea {
435	  background: #0f172a;
436	  border: 1px solid #334155;
437	  border-radius: 8px;
438	  color: #e2e8f0;
439	  font-size: 0.88rem;
440	  line-height: 1.6;
441	  padding: 10px 14px;
442	  resize: vertical;
443	  outline: none;
444	  width: 100%;
445	  box-sizing: border-box;
446	  transition: border-color 0.2s;
447	  font-family: inherit;
448	}
449	
450	.inc-notes-textarea:focus {
451	  border-color: #3b82f6;
452	}
453	
454	.inc-notes-textarea::placeholder {
455	  color: #475569;
456	}
457	
458	/* --- Primary save button --- */
459	.inc-save-btn {
460	  background: #2563eb;
461	  color: white;
462	  border: none;
463	  padding: 10px 22px;
464	  border-radius: 8px;
465	  font-weight: 700;
466	  font-size: 0.88rem;
467	  cursor: pointer;
468	  transition: background 0.2s, transform 0.15s;
469	}
470	
471	.inc-save-btn:hover:not(:disabled) {
472	  background: #1d4ed8;
473	  transform: translateY(-1px);
474	}
475	
476	.inc-save-btn:disabled {
477	  opacity: 0.6;
478	  cursor: not-allowed;
479	}
480	
481	/* --- Loading indicator --- */
482	.inc-loading-bar {
483	  color: #64748b;
484	  font-size: 0.85rem;
485	  padding: 4px 0 14px 0;
486	  letter-spacing: 0.03em;
487	}
488	
489	/* --- Responsive: single column on small screens --- */
490	@media (max-width: 600px) {
491	  .inc-form-grid {
492	    grid-template-columns: 1fr;
493	  }
494	
495	  .inc-create-modal {
496	    padding: 20px;
497	    width: 95%;
498	  }
499	}
500	
501	/* --- Manual source badge --- */
502	.inc-source-manual {
503	  background: rgba(148, 163, 184, 0.1);
504	  color: #94a3b8;
505	  border: 1px solid rgba(148, 163, 184, 0.2);
506	}
507	
508	/* --- Locked source field in create modal --- */
509	.inc-source-locked {
510	  display: flex;
511	  align-items: center;
512	  gap: 10px;
513	  padding: 8px 0 2px 0;
514	}
515	
516	.inc-source-locked-note {
517	  font-size: 0.72rem;
518	  color: #475569;
519	  letter-spacing: 0.02em;
520	}
521	
522	/* --- Manual row tint --- */
523	.management-table .inc-row-manual {
524	  background-color: rgba(120, 105, 88, 0.09);
525	}
526	
527	.management-table .inc-row-manual:hover {
528	  background-color: rgba(120, 105, 88, 0.14);
529	}
530	
531	/* --- New row slide-in animation --- */
532	@keyframes incRowSlideIn {
533	  from {
534	    opacity: 0;
535	    transform: translateY(-10px);
536	  }
537	  to {
538	    opacity: 1;
539	    transform: translateY(0);
540	  }
541	}
542	
543	.inc-row-new {
544	  animation: incRowSlideIn 0.4s ease-out forwards;
545	}
546	
547	/* --- Back to top button --- */
548	.inc-back-top {
549	  position: fixed;
550	  bottom: 32px;
551	  transform: translateX(-50%);
552	  width: 42px;
553	  height: 42px;
554	  background: linear-gradient(135deg, #2563eb, #0891b2);
555	  color: white;
556	  border: 1px solid rgba(147, 197, 253, 0.3);
557	  border-radius: 50%;
558	  font-size: 1.1rem;
559	  font-weight: 700;
560	  cursor: pointer;
561	  display: flex;
562	  align-items: center;
563	  justify-content: center;
564	  box-shadow: 0 4px 16px rgba(37, 99, 235, 0.35);
565	  z-index: 200;
566	  opacity: 0;
567	  pointer-events: none;
568	  transition: opacity 0.3s ease, transform 0.3s ease, box-shadow 0.2s ease;
569	}
570	
571	.inc-back-top.visible {
572	  opacity: 1;
573	  pointer-events: auto;
574	}
575	
576	.inc-back-top:hover {
577	  transform: translateX(-50%) translateY(-3px);
578	  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.5);
579	}
580	
581	/* --- Row delete slide-out animation --- */
582	@keyframes incRowSlideOut {
583	  from {
584	    opacity: 1;
585	    transform: translateY(0);
586	  }
587	  to {
588	    opacity: 0;
589	    transform: translateY(8px);
590	  }
591	}
592	
593	.inc-row-deleting {
594	  animation: incRowSlideOut 0.35s ease-in forwards;
595	  pointer-events: none;
596	}
597	
598	/* =========================================
599	   TOAST STACK (between filter bar and table)
600	   ========================================= */
601	
602	.inc-toast-stack {
603	  margin-bottom: 12px;
604	}
605	
606	/* Enter animation: expand height + fade in, pushing table down */
607	@keyframes incToastEnter {
608	  from {
609	    max-height: 0;
610	    opacity: 0;
611	    padding-top: 0;
612	    padding-bottom: 0;
613	    margin-bottom: 0;
614	  }
615	  to {
616	    max-height: 80px;
617	    opacity: 1;
618	    padding-top: 11px;
619	    padding-bottom: 11px;
620	    margin-bottom: 8px;
621	  }
622	}
623	
624	/* Exit animation: collapse height + fade out, table slides back up */
625	@keyframes incToastExit {
626	  from {
627	    max-height: 80px;
628	    opacity: 1;
629	    padding-top: 11px;
630	    padding-bottom: 11px;
631	    margin-bottom: 8px;
632	  }
633	  to {
634	    max-height: 0;
635	    opacity: 0;
636	    padding-top: 0;
637	    padding-bottom: 0;
638	    margin-bottom: 0;
639	  }
640	}
641	
642	.inc-toast-item {
643	  overflow: hidden;
644	  border-radius: 8px;
645	  border-left: 3px solid;
646	  font-size: 0.875rem;
647	  font-weight: 500;
648	  padding: 0 16px;
649	  box-sizing: border-box;
650	  animation: incToastEnter 0.35s ease forwards;
651	  will-change: max-height, opacity;
652	}
653	
654	.inc-toast-item.removing {
655	  animation: incToastExit 0.35s ease forwards;
656	}
657	
658	/* Type variants */
659	.inc-toast-success {
660	  background: rgba(52, 211, 153, 0.08);
661	  border-color: #34d399;
662	  color: #a7f3d0;
663	}
664	
665	.inc-toast-delete {
666	  background: rgba(248, 113, 113, 0.08);
667	  border-color: #f87171;
668	  color: #fca5a5;
669	}
670	
671	.inc-toast-error {
672	  background: rgba(245, 158, 11, 0.08);
673	  border-color: #f59e0b;
674	  color: #fde68a;
675	}
676	
677	/* ---- Table: horizontal scroll + fixed layout for balanced columns ---- */
678	.dashboard-main .table-container {
679	  overflow-x: auto;
680	  overflow-y: hidden;
681	}
682	
683	.dashboard-main .management-table {
684	  min-width: 960px;
685	  table-layout: fixed;
686	}
687	
688	/* Column widths — total 100%
689	   Order: TIMESTAMP | LOCATION | PERSON | SOURCE | CONFIDENCE | SEVERITY | STATUS | ACTIONS */
690	.dashboard-main .management-table th:nth-child(1) { width: 17%; }
691	.dashboard-main .management-table th:nth-child(2) { width: 14%; }
692	.dashboard-main .management-table th:nth-child(3) { width: 13%; }
693	.dashboard-main .management-table th:nth-child(4) { width: 11%; }
694	.dashboard-main .management-table th:nth-child(5) { width: 9%;  }
695	.dashboard-main .management-table th:nth-child(6) { width: 10%; }
696	.dashboard-main .management-table th:nth-child(7) { width: 13%; }
697	.dashboard-main .management-table th:nth-child(8) { width: 13%; }
698	
699	/* Timestamp: single line, clip gracefully rather than wrap */
700	.dashboard-main .management-table td:nth-child(1) {
701	  white-space: nowrap;
702	  overflow: hidden;
703	  text-overflow: ellipsis;
704	}
705	
706	/* ---- Sticky Actions column ---- */
707	.dashboard-main .management-table th:last-child {
708	  position: sticky;
709	  right: 0;
710	  z-index: 2;
711	  background: #1a2d48;
712	}
713	
714	.dashboard-main .management-table .actions-cell {
715	  position: sticky;
716	  right: 0;
717	  z-index: 1;
718	  background: #132035;
719	}
720	
721	/*
722	 * box-shadow on <th>/<td> is silently ignored by all browsers when
723	 * border-collapse: collapse is set on the table — use a pseudo-element
724	 * instead, which is a regular box and renders the shadow correctly.
725	 */
726	.dashboard-main .management-table th:last-child::before,
727	.dashboard-main .management-table .actions-cell::before {
728	  content: '';
729	  position: absolute;
730	  top: 0;
731	  bottom: 0;
