/* =========================================
   INCIDENT DASHBOARD — IncidentDashboard.css
   Extends Management.css + Users.css patterns.
   ========================================= */

/* --- Summary Stat Cards --- */
.inc-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 24px;
}

.inc-stat-card {
  background: #1e2539;
  border: 1px solid #2d364f;
  border-radius: 12px;
  padding: 22px 24px;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s, border-color 0.2s;
}

.inc-stat-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
}

.inc-stat-card:hover {
  transform: translateY(-2px);
  border-color: #334155;
}

.inc-stat-blue::before  { background: #3b82f6; }
.inc-stat-red::before   { background: #f87171; }
.inc-stat-orange::before { background: #f59e0b; }
.inc-stat-green::before  { background: #34d399; }

.inc-stat-blue  { border-left: 4px solid #3b82f6; }
.inc-stat-red   { border-left: 4px solid #f87171; }
.inc-stat-orange { border-left: 4px solid #f59e0b; }
.inc-stat-green  { border-left: 4px solid #34d399; }

/* Override the ::before left bar since we're using border-left */
.inc-stat-card::before { display: none; }

.inc-stat-value {
  font-size: 2.2rem;
  font-weight: 800;
  color: #f8fafc;
  line-height: 1;
  margin-bottom: 6px;
}

.inc-stat-blue  .inc-stat-value { color: #60a5fa; }
.inc-stat-red   .inc-stat-value { color: #f87171; }
.inc-stat-orange .inc-stat-value { color: #f59e0b; }
.inc-stat-green  .inc-stat-value { color: #34d399; }

.inc-stat-label {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
  color: #64748b;
}

/* --- AI vs Manual source counter chips --- */
.inc-source-counter {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
}

.inc-source-chip {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  white-space: nowrap;
  border: 1px solid;
}

.inc-source-chip-ai {
  background: rgba(192, 132, 252, 0.10);
  color: #c084fc;
  border-color: rgba(192, 132, 252, 0.25);
}

.inc-source-chip-manual {
  background: rgba(148, 163, 184, 0.09);
  color: #94a3b8;
  border-color: rgba(148, 163, 184, 0.20);
}

.inc-source-chip-divider {
  color: #334155;
  font-size: 0.85rem;
  user-select: none;
}

/* --- Filter Bar --- */
.inc-filter-bar {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.inc-search-input {
  flex: 1;
  min-width: 200px;
  padding: 9px 14px;
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 8px;
  color: #e2e8f0;
  font-size: 0.9rem;
  outline: none;
  transition: border-color 0.2s;
}

.inc-search-input::placeholder {
  color: #475569;
}

.inc-search-input:focus {
  border-color: #3b82f6;
}

.inc-select {
  padding: 9px 12px;
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 8px;
  color: #e2e8f0;
  font-size: 0.85rem;
  outline: none;
  cursor: pointer;
  transition: border-color 0.2s;
}

.inc-select:focus {
  border-color: #3b82f6;
}

/* --- Incident Badges --- */
.inc-badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

/* Severity */
.inc-severity-critical {
  background: rgba(248, 113, 113, 0.12);
  color: #f87171;
  border: 1px solid rgba(248, 113, 113, 0.25);
}

.inc-severity-high {
  background: rgba(245, 158, 11, 0.12);
  color: #f59e0b;
  border: 1px solid rgba(245, 158, 11, 0.25);
}

.inc-severity-medium {
  background: rgba(251, 191, 36, 0.12);
  color: #fbbf24;
  border: 1px solid rgba(251, 191, 36, 0.25);
}

.inc-severity-low {
  background: rgba(59, 130, 246, 0.12);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.25);
}

/* AI Source */
.inc-source-fr {
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.25);
}

.inc-source-od {
  background: rgba(192, 132, 252, 0.12);
  color: #c084fc;
  border: 1px solid rgba(192, 132, 252, 0.25);
}

/* Resolution Status */
.inc-status-active {
  background: rgba(248, 113, 113, 0.12);
  color: #f87171;
  border: 1px solid rgba(248, 113, 113, 0.25);
}

.inc-status-investigating {
  background: rgba(245, 158, 11, 0.12);
  color: #f59e0b;
  border: 1px solid rgba(245, 158, 11, 0.25);
}

.inc-status-escalated {
  background: rgba(251, 191, 36, 0.12);
  color: #fbbf24;
  border: 1px solid rgba(251, 191, 36, 0.25);
}

.inc-status-cleared {
  background: rgba(52, 211, 153, 0.12);
  color: #34d399;
  border: 1px solid rgba(52, 211, 153, 0.25);
}

/* --- Detail Modal (wider than default modal-content) --- */
.inc-detail-modal {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 16px;
  padding: 30px;
  width: 90%;
  max-width: 620px;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6);
  animation: scaleUp 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.inc-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid #334155;
}

.inc-modal-header h2 {
  font-size: 1.25rem;
  font-weight: 700;
  color: #f8fafc;
  margin: 0 0 4px 0;
}

/* --- Two-column detail grid --- */
.inc-detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px 24px;
  margin-bottom: 20px;
}

.inc-detail-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.inc-detail-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
  color: #64748b;
}

.inc-detail-value {
  font-size: 0.92rem;
  color: #e2e8f0;
  font-weight: 500;
  overflow-wrap: break-word;
  word-break: break-word;
  min-width: 0;
}

/* --- Notes section --- */
.inc-notes-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 16px;
  border-top: 1px solid #1e293b;
}

.inc-notes-box {
  background: #0f172a;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 12px 16px;
  color: #94a3b8;
  font-size: 0.88rem;
  line-height: 1.6;
  min-height: 56px;
}

/* --- Person cell — reuse user-info pattern inline --- */
.inc-person-cell {
  display: flex;
  align-items: center;
  gap: 10px;
}

.inc-person-initial {
  width: 28px;
  height: 28px;
  background: linear-gradient(135deg, #3b82f6, #0891b2);
  color: white;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-weight: 700;
  font-size: 0.78rem;
  flex-shrink: 0;
}

/* =========================================
   RESPONSIVE
   ========================================= */
@media (max-width: 1024px) {
  .inc-stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .inc-stats-grid {
    grid-template-columns: 1fr 1fr;
    gap: 12px;
  }

  .inc-filter-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .inc-search-input,
  .inc-select {
    width: 100%;
  }

  .inc-detail-grid {
    grid-template-columns: 1fr;
  }

  .inc-detail-modal {
    padding: 20px;
    width: 95%;
  }
}

@media (max-width: 480px) {
  .inc-stats-grid {
    grid-template-columns: 1fr;
  }
}

/* =========================================
   CRUD ADDITIONS
   ========================================= */

/* --- "+ Log Incident" header button --- */
.inc-create-btn {
  background: linear-gradient(135deg, #2563eb, #0891b2);
  color: white;
  border: 1px solid rgba(147, 197, 253, 0.35);
  padding: 10px 18px;
  border-radius: 8px;
  font-weight: 700;
  font-size: 0.88rem;
  cursor: pointer;
  white-space: nowrap;
  transition: transform 0.15s, box-shadow 0.15s;
  box-shadow: 0 6px 18px rgba(37, 99, 235, 0.2);
  align-self: center;
}

.inc-create-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 24px rgba(37, 99, 235, 0.35);
}

/* --- Create modal (wider than detail modal) --- */
.inc-create-modal {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 16px;
  padding: 30px;
  width: 90%;
  max-width: 660px;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6);
  animation: scaleUp 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* --- Form grid inside create modal --- */
.inc-form {
  margin-top: 20px;
}

.inc-form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px 20px;
}

.inc-form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.inc-form-full {
  grid-column: 1 / -1;
}

/* --- Textarea (create form + edit mode) --- */
.inc-notes-textarea {
  background: #0f172a;
  border: 1px solid #334155;
  border-radius: 8px;
  color: #e2e8f0;
  font-size: 0.88rem;
  line-height: 1.6;
  padding: 10px 14px;
  resize: vertical;
  outline: none;
  width: 100%;
  box-sizing: border-box;
  transition: border-color 0.2s;
  font-family: inherit;
}

.inc-notes-textarea:focus {
  border-color: #3b82f6;
}

.inc-notes-textarea::placeholder {
  color: #475569;
}

/* --- Primary save button --- */
.inc-save-btn {
  background: #2563eb;
  color: white;
  border: none;
  padding: 10px 22px;
  border-radius: 8px;
  font-weight: 700;
  font-size: 0.88rem;
  cursor: pointer;
  transition: background 0.2s, transform 0.15s;
}

.inc-save-btn:hover:not(:disabled) {
  background: #1d4ed8;
  transform: translateY(-1px);
}

.inc-save-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* --- Loading indicator --- */
.inc-loading-bar {
  color: #64748b;
  font-size: 0.85rem;
  padding: 4px 0 14px 0;
  letter-spacing: 0.03em;
}

/* --- Responsive: single column on small screens --- */
@media (max-width: 600px) {
  .inc-form-grid {
    grid-template-columns: 1fr;
  }

  .inc-create-modal {
    padding: 20px;
    width: 95%;
  }
}

/* --- Manual source badge --- */
.inc-source-manual {
  background: rgba(148, 163, 184, 0.1);
  color: #94a3b8;
  border: 1px solid rgba(148, 163, 184, 0.2);
}

/* --- Locked source field in create modal --- */
.inc-source-locked {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0 2px 0;
}

.inc-source-locked-note {
  font-size: 0.72rem;
  color: #475569;
  letter-spacing: 0.02em;
}

/* --- Manual row tint --- */
.management-table .inc-row-manual {
  background-color: rgba(120, 105, 88, 0.09);
}

.management-table .inc-row-manual:hover {
  background-color: rgba(120, 105, 88, 0.14);
}

/* --- New row slide-in animation --- */
@keyframes incRowSlideIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.inc-row-new {
  animation: incRowSlideIn 0.4s ease-out forwards;
}

/* --- Back to top button --- */
.inc-back-top {
  position: fixed;
  bottom: 32px;
  transform: translateX(-50%);
  width: 42px;
  height: 42px;
  background: linear-gradient(135deg, #2563eb, #0891b2);
  color: white;
  border: 1px solid rgba(147, 197, 253, 0.3);
  border-radius: 50%;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 16px rgba(37, 99, 235, 0.35);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s ease, box-shadow 0.2s ease;
}

.inc-back-top.visible {
  opacity: 1;
  pointer-events: auto;
}

.inc-back-top:hover {
  transform: translateX(-50%) translateY(-3px);
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.5);
}

/* --- Row delete slide-out animation --- */
@keyframes incRowSlideOut {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(8px);
  }
}

.inc-row-deleting {
  animation: incRowSlideOut 0.35s ease-in forwards;
  pointer-events: none;
}

/* =========================================
   TOAST STACK (between filter bar and table)
   ========================================= */

.inc-toast-stack {
  margin-bottom: 12px;
}

/* Enter animation: expand height + fade in, pushing table down */
@keyframes incToastEnter {
  from {
    max-height: 0;
    opacity: 0;
    padding-top: 0;
    padding-bottom: 0;
    margin-bottom: 0;
  }
  to {
    max-height: 80px;
    opacity: 1;
    padding-top: 11px;
    padding-bottom: 11px;
    margin-bottom: 8px;
  }
}

/* Exit animation: collapse height + fade out, table slides back up */
@keyframes incToastExit {
  from {
    max-height: 80px;
    opacity: 1;
    padding-top: 11px;
    padding-bottom: 11px;
    margin-bottom: 8px;
  }
  to {
    max-height: 0;
    opacity: 0;
    padding-top: 0;
    padding-bottom: 0;
    margin-bottom: 0;
  }
}

.inc-toast-item {
  overflow: hidden;
  border-radius: 8px;
  border-left: 3px solid;
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0 16px;
  box-sizing: border-box;
  animation: incToastEnter 0.35s ease forwards;
  will-change: max-height, opacity;
}

.inc-toast-item.removing {
  animation: incToastExit 0.35s ease forwards;
}

/* Type variants */
.inc-toast-success {
  background: rgba(52, 211, 153, 0.08);
  border-color: #34d399;
  color: #a7f3d0;
}

.inc-toast-delete {
  background: rgba(248, 113, 113, 0.08);
  border-color: #f87171;
  color: #fca5a5;
}

.inc-toast-error {
  background: rgba(245, 158, 11, 0.08);
  border-color: #f59e0b;
  color: #fde68a;
}

/* ---- Table: horizontal scroll + fixed layout for balanced columns ---- */
.dashboard-main .table-container {
  overflow-x: auto;
  overflow-y: hidden;
}

.dashboard-main .management-table {
  min-width: 960px;
  table-layout: fixed;
}

/* Column widths — total 100%
   Order: TIMESTAMP | LOCATION | PERSON | SOURCE | CONFIDENCE | SEVERITY | STATUS | ACTIONS */
.dashboard-main .management-table th:nth-child(1) { width: 17%; }
.dashboard-main .management-table th:nth-child(2) { width: 14%; }
.dashboard-main .management-table th:nth-child(3) { width: 13%; }
.dashboard-main .management-table th:nth-child(4) { width: 11%; }
.dashboard-main .management-table th:nth-child(5) { width: 9%;  }
.dashboard-main .management-table th:nth-child(6) { width: 10%; }
.dashboard-main .management-table th:nth-child(7) { width: 13%; }
.dashboard-main .management-table th:nth-child(8) { width: 13%; }

/* Timestamp: single line, clip gracefully rather than wrap */
.dashboard-main .management-table td:nth-child(1) {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ---- Sticky Actions column ---- */
.dashboard-main .management-table th:last-child {
  position: sticky;
  right: 0;
  z-index: 2;
  background: #1a2d48;
}

.dashboard-main .management-table .actions-cell {
  position: sticky;
  right: 0;
  z-index: 1;
  background: #132035;
}

/*
 * box-shadow on <th>/<td> is silently ignored by all browsers when
 * border-collapse: collapse is set on the table — use a pseudo-element
 * instead, which is a regular box and renders the shadow correctly.
 */
.dashboard-main .management-table th:last-child::before,
.dashboard-main .management-table .actions-cell::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: -24px;
  width: 24px;
  background: linear-gradient(to right, transparent, rgba(0, 0, 0, 0.55));
  border-right: 3px solid #2d4875;
  pointer-events: none;
}

.dashboard-main .management-table tr:hover .actions-cell {
  background: #172640;
}

